function calcularIMC(){const peso=parseFloat(document.getElementById("peso").value);const estatura=parseFloat(document.getElementById("estatura").value);const resultado=document.getElementById("resultado");const imagenEstado=document.getElementById("imagenEstado");if(!peso||!estatura){resultado.textContent="Por favor ingresa tu peso y estatura.";imagenEstado.style.display="none";return}
const imc=(peso/(estatura*estatura)).toFixed(2);let estado="";let pesoIdealMin=(18.5*estatura*estatura).toFixed(1);let pesoIdealMax=(24.9*estatura*estatura).toFixed(1);if(imc<18.5){estado="Bajo peso";imagenEstado.src="img/bajopeso.webp"}else if(imc>=18.5&&imc<=24.9){estado="Peso normal";imagenEstado.src="img/normal.webp"}else if(imc>=25&&imc<=29.9){estado="Sobrepeso";imagenEstado.src="img/sobrepeso.webp"}else{estado="Obesidad";imagenEstado.src="img/obesidad.webp"}
resultado.innerHTML=`
    Tu IMC es <strong>${imc}</strong><br>
    Estado: <strong>${estado}</strong><br>
    Peso recomendado: entre <strong>${pesoIdealMin} kg</strong> y <strong>${pesoIdealMax} kg</strong>
  `;imagenEstado.style.display="block"}